// CHOOSE HERE: the word list, the batch title and the DELIVERY MODE ('file' or 'api') are set on this node (or on the Form).
// Config only holds a default mode, used when this item does not set one.
return [{ json: {
  'Word list': 'resilient — C1\n森林 — HSK4',
  'Batch title': 'Test Batch 01',
  'Delivery mode': 'file',          // 'file' or 'api'
  'When already stored': 'skip',    // 'skip' or 'overwrite' (overwrite is honoured only in file mode; api mode always skips)
  _trigger: 'manual',               // marks an operator-run execution; the form never sets it
} }];

// Code node "Config" - every setting of the workflow lives here. No secret belongs in this node:
// the Orena token and the AI key are n8n Credentials (Header Auth) chosen on the HTTP nodes.
//
// Where a value comes from (first match wins): the form / manual input -> the SETTINGS block below -> an n8n
// environment variable. n8n 2.x may block $env in Code nodes (N8N_BLOCK_ENV_ACCESS_IN_NODE); then edit SETTINGS.
const SETTINGS = {
  mode: '',                         // '' = file. 'file' | 'api'. Only a default: "Delivery mode" on the Test input node / Form wins.
  output: {
    dir: '',                        // '' = /files/orena, inside the n8n container: mount a Docker volume there (README). Env: ORENA_VOCAB_OUT_DIR
  },
  orena: {
    baseUrl: '',                    // api mode only, e.g. https://orena.example (no trailing path). Env: ORENA_BASE_URL
    allowFormOverwrite: false,      // true = a form submitter may choose duplicates=overwrite. Env: ORENA_VOCAB_ALLOW_FORM_OVERWRITE=true
  },
  ai: {
    enabled: true,                  // AI only fills gaps the dictionaries leave; with no endpoint/model it is simply off
    endpoint: '',                   // OpenAI-compatible chat completions URL. Env: AI_ENDPOINT
    model: '',                      // Env: AI_MODEL
  },
  metadata: {
    // What the generator can honestly claim. It reads Free Dictionary (Wiktionary, CC BY-SA), Tatoeba (CC BY 2.0 FR),
    // CC-CEDICT / CVDICT (CC BY-SA), Unihan and Make Me a Hanzi: attribution / share-alike terms apply, and no one has
    // cleared this batch. Authored entries land pending_review whatever is written here (D-178); raise these only
    // after a human has actually checked the rights and the batch is a whole set.
    rights_status: 'unknown',
    completeness: 'partial',
  },
};

const DEFAULT_OUTPUT_DIR = '/files/orena';
const env = k => { try { return ($env && $env[k]) || ''; } catch (e) { return ''; } };
const flag = v => ['1', 'true', 'yes', 'on'].includes(String(v || '').trim().toLowerCase());
const form = $input.first().json || {};
const pick = (...keys) => { for (const k of keys) if (form[k] !== undefined && form[k] !== null && String(form[k]).trim() !== '') return String(form[k]); return ''; };
// Only the manual "Test input" path is operator-controlled. Anything else arrives through the form trigger (a webhook).
const trusted = form._trigger === 'manual';
const now = new Date();
const runId = now.toISOString().replace(/[-:]/g, '').replace(/\..+/, '').replace('T', '-');   // 20261013-091500

// Delivery mode: the input item wins ("Delivery mode" on the Test input node or the Form); else SETTINGS.mode; else file.
const modeFromInput = pick('Delivery mode', 'mode');
let mode = (modeFromInput || SETTINGS.mode || 'file').toLowerCase();
const modeSource = modeFromInput ? 'input (Test input node / Form)' : (SETTINGS.mode ? 'Config default' : 'default (file)');
if (!['file', 'api'].includes(mode)) throw new Error("Delivery mode must be 'file' or 'api'");

let duplicates = (pick('When already stored', 'duplicates') || 'skip').toLowerCase();
if (!['skip', 'overwrite'].includes(duplicates)) throw new Error("duplicates must be 'skip' or 'overwrite'");
let duplicatesNote = '';
const overwriteAllowed = trusted || SETTINGS.orena.allowFormOverwrite || flag(env('ORENA_VOCAB_ALLOW_FORM_OVERWRITE'));
if (duplicates === 'overwrite' && !overwriteAllowed) {
  duplicates = 'skip';
  duplicatesNote = "'overwrite' was requested through the form, which is not allowed to overwrite; 'skip' was used instead";
}

// api mode talks to Orena with a service credential, which Orena only lets add pending-review content with duplicates=skip.
if (duplicates === 'overwrite' && mode === 'api') {
  duplicates = 'skip';
  duplicatesNote = "'overwrite' is not available in api mode (the service credential may only skip duplicates); 'skip' was used";
}

const dir = String(SETTINGS.output.dir || env('ORENA_VOCAB_OUT_DIR') || DEFAULT_OUTPUT_DIR).replace(/\/+$/, '');
if (!/^\/[A-Za-z0-9_\-. \/]+$/.test(dir) || dir.split('/').includes('..')) throw new Error('output.dir must be an absolute path without ".."');

const baseUrl = String(SETTINGS.orena.baseUrl || env('ORENA_BASE_URL') || '').trim().replace(/\/+$/, '');
if (baseUrl && !/^https?:\/\/[^\s/]+$/i.test(baseUrl)) throw new Error('orena.baseUrl must be an origin such as https://orena.example');

const aiEndpoint = String(SETTINGS.ai.endpoint || env('AI_ENDPOINT') || '').trim();
const aiModel = String(SETTINGS.ai.model || env('AI_MODEL') || '').trim();

const config = {
  runId,
  trusted,
  mode,
  modeSource,
  duplicates,
  duplicatesNote,

  input: {
    text: pick('Word list', 'words'),             // one per line: word - level [- Vietnamese meaning]
    title: pick('Batch title', 'title'),
    collectionId: pick('Collection ID', 'collection_id'),
  },

  orena: {
    baseUrl,
    previewUrl: baseUrl + '/api/admin/vocabulary/preview',
    importUrl: baseUrl + '/api/admin/vocabulary/import',
    configured: !!baseUrl,
    fileFormat: 'jsonl',            // 'jsonl' | 'json'
  },

  metadata: { ...SETTINGS.metadata },

  record: {
    status: 'draft',                // the generator never publishes; Orena ignores the file's status and holds the set for review
    allowedStatuses: ['draft'],
    maxExamples: 2,                 // 1-4 (schema)
    // The level is what the operator typed. Nothing here checks it against a word list, and the sources say so.
    levelSourceEN: 'operator-supplied CEFR level (not checked against a word list)',
    levelSourceZH: 'operator-supplied HSK level (not checked against the HSK 3.0 list)',
  },

  sources: {
    freeDictionary: 'https://api.dictionaryapi.dev/api/v2/entries/en/',
    tatoebaSearch: 'https://tatoeba.org/en/api_v0/search',
    cedict: 'https://www.mdbg.net/chinese/export/cedict/cedict_1_0_ts_utf-8_mdbg.txt.gz',
    cvdict: 'https://raw.githubusercontent.com/ph0ngp/CVDICT/main/CVDICT.u8',
    makeMeAHanzi: 'https://raw.githubusercontent.com/skishore/makemeahanzi/master/dictionary.txt',
    unihan: 'https://www.unicode.org/Public/UCD/latest/ucd/Unihan.zip',
  },
  zhLookup: { path: dir + '/zh_lookup.json', rebuild: false },

  ai: {
    enabled: !!SETTINGS.ai.enabled,
    endpoint: aiEndpoint,
    model: aiModel,
    fill: { pos: true, meaning_vi: true, translation_vi: true, examples: true, ipa: true },
  },
  // IPA the dictionary does not tag as UK or US: 'none' = do not use it (AI fills or the word is rejected)
  untaggedIpaAs: 'none',

  output: { dir },
};

config.record.maxExamples = Math.min(4, Math.max(1, config.record.maxExamples | 0));
if (config.record.status === 'published') throw new Error('The generator never publishes: record.status cannot be published');
// AI is on only with a valid http(s) endpoint AND a model. A credential on the HTTP node never counts as configuration.
const aiUrlOk = /^https?:\/\/[^\s/]+/i.test(config.ai.endpoint);
config.ai.active = !!(config.ai.enabled && aiUrlOk && config.ai.model);
config.ai.reason = config.ai.active ? '' : (!config.ai.enabled ? 'AI not configured: disabled in Config' :
  `AI not configured: missing ${[!aiUrlOk && (config.ai.endpoint ? 'a valid http(s) endpoint' : 'endpoint'), !config.ai.model && 'model'].filter(Boolean).join('/')}`);
config.ai.host = config.ai.active ? (/^https?:\/\/([^\s/]+)/i.exec(config.ai.endpoint) || [])[1] || '' : '';

return [{ json: config }];

// Code node "Output folder probe" - n8n's Read/Write Files node does not create folders, so a fresh install would fail
// on the first write (ENOENT realpath). This writes a tiny marker into the output folder FIRST; "Check output folder"
// turns a failure into one clear message before any download or enrichment is spent.
const cfg = $('Config').first().json;
const path = `${cfg.output.dir}/.orena-write-check`;
return [{
  json: { path },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from('ok\n', 'utf8'), '.orena-write-check', 'text/plain') },
}];

// Code node "Check output folder" - stops the run early, with the folder to create, when the probe could not be written.
const cfg = $('Config').first().json;
const r = $input.first();
const err = !r ? 'no result from the write node' : (r.json && r.json.error);
if (err) {
  const msg = String((err && (err.message || err.description)) || err).slice(0, 300);
  throw new Error(`The output folder ${cfg.output.dir} is not writable (${msg}). n8n does not create it: create the folder inside the ` +
    `mounted volume first (for example: mkdir -p ./orena-files/orena for a mount of ./orena-files at /files), make it writable ` +
    `by the n8n user, and set N8N_RESTRICT_FILE_ACCESS_TO to a parent of it. Nothing was generated.`);
}
return [{ json: { ok: true } }];

// ===== Orena vocabulary generator | shared helpers (inlined into every Code node that needs them) =====
const TONE_MARKS = { a: 'āáǎà', e: 'ēéěè', i: 'īíǐì', o: 'ōóǒò', u: 'ūúǔù', 'ü': 'ǖǘǚǜ' };

function syllableToMark(syl) {
  const m = /^([A-Za-zü:]+)([1-5])$/.exec(syl);
  if (!m) return syl.replace(/u:/g, 'ü').replace(/v/g, 'ü');
  const body = m[1].replace(/u:/g, 'ü').replace(/U:/g, 'Ü').replace(/v/g, 'ü');
  const tone = +m[2];
  if (tone === 5) return body;
  const low = body.toLowerCase();
  let idx;
  if (low.includes('a')) idx = low.indexOf('a');
  else if (low.includes('e')) idx = low.indexOf('e');
  else if (low.includes('ou')) idx = low.indexOf('o');
  else idx = Math.max(...['i', 'o', 'u', 'ü'].map(v => low.lastIndexOf(v)));
  if (idx < 0) return body;
  let mk = TONE_MARKS[low[idx]][tone - 1];
  if (body[idx] !== low[idx]) mk = mk.toUpperCase();
  return body.slice(0, idx) + mk + body.slice(idx + 1);
}

function joinSyllables(arr) {
  let out = '';
  arr.forEach((s, i) => {
    if (i && s && 'aeo'.includes(s.normalize('NFD')[0].toLowerCase())) out += "'";
    out += s;
  });
  return out;
}

function slug(s) { return String(s).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, ''); }

function fnv1a(str) {
  let h = 0x811c9dc5;
  for (const ch of String(str)) { h ^= ch.codePointAt(0); h = Math.imul(h, 0x01000193) >>> 0; }
  return h.toString(16).padStart(8, '0');
}

const CJK_RE = /[\u3400-\u9fff\uf900-\ufaff]/;
function isCjk(s) { return CJK_RE.test(s); }

// Deterministic id, a function of the language and the headword only (never of the run, the time or the order):
// a rerun with the same input yields the same ids. The id pattern of the repo schema is ^[a-z]{2}(-[A-Za-z]+)?:[a-z0-9_-]+$.
// Orena itself keys an entry by (language, term, first part of speech); this id is its editorial handle (provenance.source_id).
function makeId(lang, word) {
  if (lang === 'zh-Hans') return 'zh-Hans:' + Array.from(String(word).trim()).map(c => c.codePointAt(0).toString(16)).join('-');
  const w = String(word).trim();
  const s = slug(w);
  const clean = /^[a-z0-9]+(?:[ '-][a-z0-9]+)*$/i.test(w);
  return 'en:' + ((s && clean) ? s : (s ? s + '-' : 'w-') + fnv1a(w.toLowerCase()).slice(0, 6));
}

function normLevel(lang, raw) {
  let v = String(raw || '').trim().toUpperCase().replace(/\s+/g, '');
  if (!v) return null;
  if (lang === 'zh-Hans') {
    v = v.replace(/^HSK/, '');
    if (/^[789]$|^7-9$|^7–9$/.test(v)) return '7-9';
    return /^[1-6]$/.test(v) ? v : null;
  }
  v = v.replace(/^CEFR/, '');
  return /^(A1|A2|B1|B2|C1|C2)$/.test(v) ? v : null;
}

function cleanGlosses(glosses, limit = 3) {
  const out = [];
  for (let g of glosses || []) {
    if (/^(CL:|variant of|old variant|see |also written|surname )/.test(g)) continue;
    g = g.replace(/\s*\[[^\]]*\]/g, '').replace(/\|[^\s,;)]+/g, '').trim();
    if (g) out.push(g);
  }
  return out.slice(0, limit);
}

function measureWords(glosses) {
  const res = [];
  for (const g of glosses || []) {
    const m = /^CL:(.*)$/.exec(g);
    if (!m) continue;
    const re = /([^\s,|\[]+?)(?:\|([^\s,\[]+))?\[([^\]]+)\]/g;
    let mm;
    while ((mm = re.exec(m[1]))) res.push({ mw: mm[2] || mm[1], pinyin: joinSyllables(mm[3].split(/\s+/).map(syllableToMark)) });
  }
  return res;
}

// lookup.cedict[simp] = [[pinyinWithToneNumbers, [glosses...]], ...]
function pickEntry(entries) {
  if (!entries || !entries.length) return null;
  return entries.find(e => e[0] && /^[a-z]/.test(e[0])) || entries[0];
}

function kangxiRadicalChar(rs) {
  const n = parseInt(String(rs || '').split(/\s+/)[0].split('.')[0], 10);
  if (!(n >= 1 && n <= 214)) return null;
  return String.fromCodePoint(0x2F00 + n - 1).normalize('NFKC');
}

function components(decomp) { return Array.from((decomp || '').replace(/[\u2FF0-\u2FFF？?]/g, '')); }

const ZH_PUNCT = { '。': '.', '，': ',', '、': ',', '？': '?', '！': '!', '：': ':', '；': ';', '“': '"', '”': '"', '（': '(', '）': ')', '《': '"', '》': '"' };

// Sentence pinyin: longest-match segmentation over CC-CEDICT; the headword is always one word.
// Returns ['', headPy] when any CJK character is unknown, so no half-guessed reading is ever written.
function sentencePinyin(text, headword, cedict) {
  const wordPy = w => { const e = pickEntry(cedict[w]); return e ? joinSyllables(e[0].split(/\s+/).map(syllableToMark)) : null; };
  const headPy = wordPy(headword) || '';
  const tokens = [];
  let unknown = false;
  text.split(headword).forEach((seg, si) => {
    if (si) tokens.push(headPy || headword);
    const chars = Array.from(seg);
    let i = 0;
    while (i < chars.length) {
      let done = false;
      for (let L = Math.min(8, chars.length - i); L > 0; L--) {
        const p = wordPy(chars.slice(i, i + L).join(''));
        if (p) { tokens.push(p); i += L; done = true; break; }
      }
      if (!done) {
        const ch = chars[i];
        if (ZH_PUNCT[ch]) tokens.push('\u0000' + ZH_PUNCT[ch]);
        else if (/\s/.test(ch)) { /* drop whitespace */ }
        else { tokens.push(ch); if (isCjk(ch)) unknown = true; }
        i++;
      }
    }
  });
  let out = '';
  for (const t of tokens) out += t.startsWith('\u0000') ? t.slice(1) : (out && !/["(]$/.test(out) ? ' ' : '') + t;
  out = out.trim();
  if (unknown || !headPy) return ['', headPy];
  return [out ? out[0].toUpperCase() + out.slice(1) : '', headPy];
}

// Tatoeba api_v0: results[].translations[][]; newer API: data[].translations[]
function parseTatoeba(raw) {
  let o; try { o = typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return []; }
  const arr = (o && (o.results || o.data)) || [];
  return arr.map(r => {
    const tr = [];
    const walk = x => {
      if (Array.isArray(x)) x.forEach(walk);
      else if (x && typeof x === 'object') { if (x.lang === 'vie' && x.text) tr.push(x.text); if (x.translations) walk(x.translations); }
    };
    walk(r.translations);
    return { text: String(r.text || '').trim(), vi: tr[0] || '', source: 'tatoeba' };
  }).filter(x => x.text);
}

function pickExamples(cands, matchFn, max) {
  const seen = new Set();
  return cands
    .filter(c => { if (seen.has(c.text)) return false; seen.add(c.text); return c.text.length >= 4 && c.text.length <= 120 && matchFn(c.text); })
    .sort((a, b) => (!a.vi - !b.vi) || (Math.abs(a.text.length - 35) - Math.abs(b.text.length - 35)) || (a.text < b.text ? -1 : a.text > b.text ? 1 : 0))
    .slice(0, max);
}

function parseJsonSafe(raw) { try { return typeof raw === 'string' ? JSON.parse(raw) : raw; } catch (e) { return null; } }
function escRe(s) { return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'); }

// An IPA transcription as the card stores it: slash-delimited ("/rɪˈzɪliənt/"). A bare transcription is wrapped;
// anything else (brackets, empty) is returned unchanged so the validator rejects it rather than the workflow guessing.
function normIpa(s) {
  const t = String(s || '').trim();
  if (!t) return '';
  if (/^\/[^\/]+\/$/.test(t)) return t;
  if (/^[\[(]/.test(t) || /[\])]$/.test(t) || t.includes('/')) return t;
  return '/' + t + '/';
}

const POS_CODES = ['noun', 'verb', 'adjective', 'adverb', 'pronoun', 'preposition', 'conjunction', 'determiner', 'interjection', 'numeral', 'measure_word', 'particle', 'phrase', 'idiom'];
const POS_VI = { noun: 'danh từ', verb: 'động từ', adjective: 'tính từ', adverb: 'trạng từ', pronoun: 'đại từ', preposition: 'giới từ',
  conjunction: 'liên từ', interjection: 'thán từ', determiner: 'từ hạn định', numeral: 'số từ', measure_word: 'lượng từ', particle: 'trợ từ',
  phrase: 'cụm từ', idiom: 'thành ngữ' };
const POS_ZH = { noun: '名词', verb: '动词', adjective: '形容词', adverb: '副词', pronoun: '代词', preposition: '介词', conjunction: '连词',
  interjection: '叹词', numeral: '数词', measure_word: '量词', particle: '助词', phrase: '短语', idiom: '成语' };
const posObj = (code, lang) => ({ code, label_native: lang === 'zh-Hans' ? (POS_ZH[code] || code) : code, label_vi: POS_VI[code] || code });
// ===== end of shared helpers =====


// Code node "Parse words" - reads the list, detects each line's language, normalises the level, derives the deterministic id.
// Line format:  word - level [- Vietnamese meaning]   (separators: tab, an em/en dash, " - ", comma, semicolon, pipe)
const cfg = $('Config').first().json;
const words = [], inputIssues = [], seen = new Map();
String(cfg.input.text || '').split(/\r?\n/).forEach((raw, lineNo) => {
  const line = raw.trim();
  if (!line || line.startsWith('#')) return;
  const parts = line.split(/\t|\s+[—–]\s+|\s*[—–]\s*|\s+-\s+|\s*[,;|]\s*/).map(s => s.trim()).filter(Boolean);
  const word = parts[0];
  const lang = isCjk(word) ? 'zh-Hans' : 'en';
  const levelRaw = parts[1] || '';
  const level = normLevel(lang, levelRaw);
  const meaningVi = parts.slice(2).join(', ');
  const id = makeId(lang, word);
  if (seen.has(id)) { inputIssues.push({ line: lineNo + 1, word, issue: `same id as line ${seen.get(id)}; this line was ignored` }); return; }
  seen.set(id, lineNo + 1);
  words.push({ line: lineNo + 1, word, lang, level, levelRaw, meaningVi, id });
});
if (!words.length) throw new Error('The word list is empty');
return [{ json: { words, inputIssues, hasZh: words.some(w => w.lang === 'zh-Hans'), hasEn: words.some(w => w.lang === 'en') } }];

// ===== Orena vocabulary generator | shared helpers (inlined into every Code node that needs them) =====
const TONE_MARKS = { a: 'āáǎà', e: 'ēéěè', i: 'īíǐì', o: 'ōóǒò', u: 'ūúǔù', 'ü': 'ǖǘǚǜ' };

