    if (!ipa.uk && !ipa.us && untagged && ['uk', 'us'].includes(cfg.untaggedIpaAs)) { ipa[cfg.untaggedIpaAs] = normIpa(untagged); warnings.push(`IPA is not tagged UK/US; assigned to ${cfg.untaggedIpaAs}`); }
    if (entries.length && !ipa.uk && !ipa.us) {
