    const re = new RegExp('\\b' + escRe(w.word) + '\\b', 'i');
    const picked = pickExamples(cands, t => re.test(t), cfg.record.maxExamples);
    picked.forEach(c => tags.add('src:' + (c.source === 'tatoeba' ? 'tatoeba' : 'free-dictionary')));
