const passed = checks.every(c => c.ok);
return sent.map((s, k) => ({
  json: { ...s.json, passed, preview: { ok: checks[k].ok, status: checks[k].status, reasons: checks[k].reasons, counts: checks[k].counts, existing: checks[k].existing, warnings: checks[k].warnings } },
  ...(passed ? { binary: s.binary } : {}),
}));

// ===== Orena vocabulary generator | strict readers of Orena's admin vocabulary responses =====
// Contract source: app.py `admin_vocabulary_source_preview` / `admin_vocabulary_source_import` and
// `_authored_preview` (see integrations/n8n/README.md). Anything that does not match EXACTLY blocks the import.

// The HTTP Request node (full response, text format) hands over { statusCode, headers, body } (or { data } for the body).
function readHttp(resp) {
  if (!resp || typeof resp !== 'object') return { ok: false, reason: 'no response from Orena' };
  if (resp.error) return { ok: false, reason: 'request to Orena failed: ' + String((resp.error && (resp.error.message || resp.error.description)) || JSON.stringify(resp.error)).slice(0, 300) };
  const status = resp.statusCode;
  if (!Number.isInteger(status)) return { ok: false, reason: 'the response has no HTTP status code' };
  const raw = resp.body !== undefined ? resp.body : resp.data;
  const snippet = String(typeof raw === 'string' ? raw : JSON.stringify(raw)).replace(/\s+/g, ' ').slice(0, 200);
  if (status < 200 || status >= 300) return { ok: false, status, reason: `HTTP ${status}: ${snippet}` };
  const headers = resp.headers && typeof resp.headers === 'object' ? resp.headers : {};
  const ctype = String(Object.entries(headers).find(([k]) => k.toLowerCase() === 'content-type')?.[1] || '').toLowerCase();
  if (ctype && !ctype.includes('json')) return { ok: false, status, reason: `the response is not JSON (content-type '${ctype.slice(0, 60)}')` };
  let body = raw;
  if (typeof raw === 'string') { try { body = JSON.parse(raw); } catch (e) { return { ok: false, status, reason: 'the response body is not JSON: ' + snippet.slice(0, 80) }; } }
  if (!body || typeof body !== 'object' || Array.isArray(body)) return { ok: false, status, reason: 'the response body is not a JSON object' };
  return { ok: true, status, body };
}

const _isObj = v => !!v && typeof v === 'object' && !Array.isArray(v);

// expected = { filename, language_code, ids: [ids in file order] }. Returns { ok, reasons[], counts, existing }.
// `ok` is true only when the response has the exact preview shape AND every row is `ready` with a known `existing`.
function checkPreview(resp, expected) {
  const http = readHttp(resp);
  const out = { ok: false, reasons: [], counts: {}, existing: {}, warnings: [], status: http.status || null };
  if (!http.ok) { out.reasons.push(http.reason); return out; }
  const items = http.body.items;
  if (!Array.isArray(items) || items.length !== 1) { out.reasons.push("unexpected preview shape: 'items' must be an array with exactly one item"); return out; }
  const item = items[0];
  if (!_isObj(item)) { out.reasons.push('unexpected preview shape: the item is not an object'); return out; }
  if (item.error) { out.reasons.push('preview error: ' + String(item.error).slice(0, 300)); return out; }
  if (item.error !== '') { out.reasons.push("unexpected preview shape: item.error must be ''"); return out; }
  if (item.filename !== expected.filename) out.reasons.push(`unexpected preview shape: filename '${item.filename}' is not '${expected.filename}'`);
  if (typeof item.content_hash !== 'string' || !item.content_hash) out.reasons.push('unexpected preview shape: no content_hash');
  const a = item.authored;
  if (!_isObj(a)) { out.reasons.push("the file was not read as authored vocabulary entries (no 'authored' section)"); return out; }
  if (a.format !== 'orena-vocab-entry') out.reasons.push(`unexpected preview shape: authored.format is '${a.format}'`);
  if (a.language_code !== expected.language_code) out.reasons.push(`the preview language '${a.language_code}' is not '${expected.language_code}'`);
  if (!Array.isArray(a.rows) || !_isObj(a.counts) || !Array.isArray(a.warnings)) { out.reasons.push('unexpected preview shape: authored.rows/counts/warnings'); return out; }
  if (a.rows.length !== expected.ids.length) out.reasons.push(`the preview has ${a.rows.length} row(s), the file has ${expected.ids.length}`);
  const tally = {};
  a.rows.forEach((row, i) => {
    if (!_isObj(row)) { out.reasons.push(`row ${i + 1}: not an object`); return; }
    const label = row.id || row.term || `row ${i + 1}`;
    tally[row.outcome] = (tally[row.outcome] || 0) + 1;
    if (row.outcome !== 'ready') { out.reasons.push(`${label}: outcome '${row.outcome}'${row.reason ? ' - ' + String(row.reason).slice(0, 200) : ''}`); return; }
    if (row.id !== expected.ids[i]) out.reasons.push(`row ${i + 1}: id '${row.id}' is not the expected '${expected.ids[i]}'`);
    if (row.existing !== 'new' && row.existing !== 'duplicate') out.reasons.push(`${label}: cannot tell what Orena already holds (existing '${row.existing}')`);
    else out.existing[row.id] = row.existing;
  });
  for (const [k, n] of Object.entries(a.counts)) if (tally[k] !== n) out.reasons.push(`unexpected preview shape: counts.${k}=${n} disagrees with the rows`);
  for (const k of Object.keys(tally)) if (!(k in a.counts)) out.reasons.push(`unexpected preview shape: counts is missing '${k}'`);
  out.counts = a.counts;
  out.warnings = a.warnings.map(w => String(w).slice(0, 300));
  out.ok = out.reasons.length === 0;
  return out;
}

// expected = { collection_id, ready: n }. The import response must show a pending_review set and no failed/conflicting row.
function checkImport(resp, expected) {
  const http = readHttp(resp);
  const out = { ok: false, reasons: [], result: null, status: http.status || null };
  if (!http.ok) { out.reasons.push(http.reason); return out; }
  const { collection, items } = http.body;
  if (!_isObj(collection) || collection.id !== expected.collection_id) out.reasons.push(`unexpected import shape: collection.id is not '${expected.collection_id}'`);
  if (_isObj(collection) && collection.catalog_status !== 'pending_review') out.reasons.push(`the collection is '${collection.catalog_status}', not pending_review (authored vocabulary must wait for review)`);
  if (!Array.isArray(items) || items.length !== 1 || !_isObj(items[0])) { out.reasons.push("unexpected import shape: 'items' must hold exactly one result"); return out; }
  const r = items[0];
  for (const k of ['imported', 'skipped', 'duplicates', 'failed']) if (!Number.isInteger(r[k])) out.reasons.push(`unexpected import shape: '${k}' is not a number`);
  if (r.status !== 'imported' && r.status !== 'skipped') out.reasons.push(`the source result is '${r.status}'${r.failure_reason ? ': ' + String(r.failure_reason).slice(0, 200) : ''}`);
  if (r.failed) out.reasons.push(`${r.failed} source(s) failed${r.failure_reason ? ': ' + String(r.failure_reason).slice(0, 200) : ''}`);
  if (Number.isInteger(r.conflicts) && r.conflicts > 0) out.reasons.push(`${r.conflicts} entr(ies) conflict with a published set and were refused`);
  out.result = { status: r.status, imported: r.imported, updated: r.updated || 0, skipped: r.skipped, duplicates: r.duplicates, conflicts: r.conflicts || 0, catalog_status: _isObj(collection) ? collection.catalog_status : null };
  out.ok = out.reasons.length === 0;
  return out;
}
// ===== end of Orena response readers =====


// Code node "Check import" - reads each import answer strictly. The set must be pending_review (authored entries never publish)
// and no source may have failed or conflicted. The local files are never touched by this step.
const sent = $('Check preview').all();
const replies = $input.all();
return sent.map((s, k) => {
  const c = checkImport((replies[k] || {}).json || null, { collection_id: s.json.collection_id, ready: s.json.ids.length });
  return { json: { collection_id: s.json.collection_id, ok: c.ok, reasons: c.reasons, result: c.result, status: c.status } };
});

// ===== Orena vocabulary generator | report builders =====
const csvCell = v => { const s = String(v === undefined || v === null ? '' : v); return /[",\r\n]/.test(s) ? '"' + s.replace(/"/g, '""') + '"' : s; };

// batch  = the single item of "Validate & group"
// sync   = { [collection_id]: { status, reasons[], preview?, import? } } (empty in file mode)
// writes = [{ role, path, ok, error }]
function buildReport(cfg, batch, sync, writes) {
  const groupSync = id => sync[id] || { status: cfg.mode === 'api' ? 'pending' : 'not_requested', reasons: [] };
  const statuses = batch.groups.map(g => groupSync(g.collection_id).status);
  let overall = 'not_requested';
  if (cfg.mode === 'api') {
    if (!batch.groups.some(g => g.readyCount)) overall = 'skipped_no_ready_records';
    else if (statuses.some(s => s === 'failed')) overall = 'failed';
    else if (statuses.some(s => s === 'blocked')) overall = 'blocked';
    else if (statuses.every(s => s === 'imported' || s === 'no_ready_records')) overall = 'imported';
    else overall = 'pending';
  }
  const rowSync = lang => { const g = batch.groups.find(x => x.lang === lang); return g ? groupSync(g.collection_id).status : ''; };
  const rows = [
    ...batch.ready.map(x => ({ line: x.line, id: x.id, headword: x.headword, lang: x.lang, status: 'ready', reasons: '', warnings: (x.warnings || []).join(' | '), collection_id: (batch.groups.find(g => g.lang === x.lang) || {}).collection_id || '', sync: rowSync(x.lang) })),
    ...batch.rejected.map(x => ({ line: x.line, id: x.id, headword: x.headword, lang: x.lang, status: 'rejected', reasons: x.reasons.join(' | '), warnings: (x.warnings || []).join(' | '), collection_id: '', sync: 'not_sent' })),
  ].sort((a, b) => a.line - b.line);
  return {
    run_id: cfg.runId,
    mode: cfg.mode,
    mode_source: cfg.modeSource,
    duplicates: cfg.duplicates,
    duplicates_note: cfg.duplicatesNote || '',
    totals: { input: batch.ready.length + batch.rejected.length, ready: batch.ready.length, rejected: batch.rejected.length },
    ai: { configured: !!cfg.ai.active, endpoint_host: cfg.ai.host || '', reason: cfg.ai.active ? '' : (cfg.ai.reason || 'AI not configured: missing endpoint/model') },
    rights_status: cfg.metadata.rights_status,
    completeness: cfg.metadata.completeness,
    sync_status: overall,
    groups: batch.groups.map(g => ({ lang: g.lang, collection_id: g.collection_id, ready: g.readyCount, rejected: g.rejectedCount, ready_file: g.readyCount ? g.readyPath : '', sync: groupSync(g.collection_id) })),
    input_issues: batch.inputIssues || [],
    writes: writes || [],
    rows,
  };
}

function reportCsv(report) {
  const head = ['line', 'id', 'headword', 'lang', 'status', 'reasons', 'warnings', 'collection_id', 'sync'];
  return [head.join(','), ...report.rows.map(r => head.map(k => csvCell(r[k])).join(','))].join('\n') + '\n';
}
// ===== end of report builders =====


// Code node "Final report" - the audit files again, now carrying the outcome of the sync (api mode) and of the first writes.
const cfg = $('Config').first().json;
const batch = $('Validate & group').first().json;
const tried = name => { try { return $(name).all().map(i => i.json); } catch (e) { return null; } };
const writes = ((tried('Check writes') || [])[0] || {}).writes || [];
const prep = tried('Prepare sync') || [];
const previews = tried('Check preview');
const imports = tried('Check import');
const sync = {};
if (cfg.mode === 'api') {
  const noop = prep.length && prep[0].noop ? prep[0] : null;
  for (const g of batch.groups) {
    if (noop) { sync[g.collection_id] = { status: noop.reason === 'no_ready_records' || !g.readyCount ? 'no_ready_records' : 'blocked', reasons: [noop.reason] }; continue; }
    if (!g.readyCount) { sync[g.collection_id] = { status: 'no_ready_records', reasons: [] }; continue; }
    const p = (previews || []).find(x => x.collection_id === g.collection_id);
    if (!p) { sync[g.collection_id] = { status: 'blocked', reasons: ['no preview result'] }; continue; }
    if (!p.passed) {
      sync[g.collection_id] = { status: 'blocked', reasons: p.preview.ok ? ['held: another file of this batch did not pass preview, so nothing was imported'] : p.preview.reasons, preview: p.preview };
      continue;
    }
    const im = (imports || []).find(x => x.collection_id === g.collection_id);
    if (!im) sync[g.collection_id] = { status: 'failed', reasons: ['no import result'], preview: p.preview };
    else sync[g.collection_id] = { status: im.ok ? 'imported' : 'failed', reasons: im.reasons, preview: p.preview, import: im.result };
  }
}
const report = buildReport(cfg, batch, sync, writes);
const add = async (role, path, text, mime, extra) => ({
  json: { role, path, ...(extra || {}) },
  binary: { data: await this.helpers.prepareBinaryData(Buffer.from(text, 'utf8'), path.split('/').pop(), mime) },
});
return [
  await add('report_json', `${cfg.output.dir}/${cfg.runId}_report.json`, JSON.stringify(report, null, 2) + '\n', 'application/json', { sync_status: report.sync_status }),
  await add('report_csv', `${cfg.output.dir}/${cfg.runId}_report.csv`, reportCsv(report), 'text/csv', { sync_status: report.sync_status }),
];

// Code node "Run summary" - what the operator sees at the end of a run: counts, the files, any non-critical write that
// failed, and the sync outcome. A failed audit write never turns a good batch into a failed one; it is simply listed here.
const cfg = $('Config').first().json;
const batch = $('Validate & group').first().json;
const final = $('Final report').all().map(i => i.json);
const firstWrites = ((() => { try { return $('Check writes').first().json; } catch (e) { return {}; } })()).writes || [];
const msgOf = e => String((e && (e.message || e.description)) || e || 'unknown error').slice(0, 300);
const results = $input.all();
const writes = [
  ...firstWrites.filter(w => w.role === 'ready' || w.role === 'rejected'),
  ...final.map((f, i) => {
    const r = results[i];
    const err = !r ? 'no result from the write node' : (r.json && r.json.error ? msgOf(r.json.error) : '');
    return { role: f.role, path: f.path, ok: !err, error: err };
  }),
];
return [{ json: {
  run_id: cfg.runId, mode: cfg.mode, mode_source: cfg.modeSource, duplicates: cfg.duplicates, duplicates_note: cfg.duplicatesNote || undefined,
  ready: batch.ready.length, rejected: batch.rejected.length,
  files: writes.filter(w => w.ok).map(w => w.path),
  non_critical_write_failures: writes.filter(w => !w.ok),
  sync_status: (final[0] || {}).sync_status || 'unknown',
  note: cfg.mode === 'api' ? 'See sync_status and the report for the Orena preview/import. Imported sets wait for review in Orena Admin.' : 'File mode: import the ready file through Orena Admin (Vocabulary import).',
} }];
